        /// <summary>The strings of Settings › MCP and its pages (connected apps, delegation agent, model order, subscription plans), registered like the update strings.</summary>
        private static void RegisterMcpStrings()
        {
            string[] languages = { "it", "es", "fr", "de", "pt" };
            foreach (string[] row in McpStrings)
                for (int i = 0; i < languages.Length; i++) Register(languages[i], row[0], row[i + 1]);
        }

